package com.example.starter.config;

import java.time.Clock;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * 时间源配置：业务时间统一取 UTC，测试可替换为可控时钟。
 */
@Configuration
public class TimeConfig {

    /**
     * 系统 UTC 时钟。
     */
    @Bean
    public Clock clock() {
        return Clock.systemUTC();
    }
}

package com.example.starter.cosmetic.domain;

/**
 * 备案状态机：公示中 → 异议审查 / 生效 → 被替代 / 注销；审查不通过与注销为终态。
 */
public enum RegistrationStatus {
    /** 公示中（形式审查已通过，公示期10个自然日）。 */
    PUBLICITY,
    /** 异议审查（公示期内收到异议）。 */
    OBJECTION_REVIEW,
    /** 已生效。 */
    EFFECTIVE,
    /** 审查不通过（终态）。 */
    REJECTED,
    /** 已被新版本替代（终态）。 */
    SUPERSEDED,
    /** 已注销（终态，重复注销幂等成功）。 */
    CANCELLED
}

package com.example.starter.cosmetic.domain;

/**
 * 备案类型：首次备案、实质变更（配方/功效宣称，重新审查并生成新编号）、简易变更（包装文字类，引用原编号）。
 */
public enum ChangeType {
    /** 首次备案。 */
    INITIAL,
    /** 实质变更：涉及配方或功效宣称，重新形式审查并生成新备案编号。 */
    SUBSTANTIAL,
    /** 简易变更：包装文字类，引用原备案编号。 */
    SIMPLE
}

package com.example.starter.cosmetic.domain;

/**
 * 功效评价试验报告结论。
 */
public enum ReportConclusion {
    /** 支持对应功效宣称。 */
    SUPPORT,
    /** 不支持对应功效宣称。 */
    NOT_SUPPORT
}

package com.example.starter.cosmetic.domain;

/**
 * 公示异议状态。
 */
public enum ObjectionStatus {
    /** 待审查。 */
    PENDING,
    /** 异议不成立，备案恢复流程。 */
    DISMISSED,
    /** 异议成立，备案不予生效。 */
    UPHELD
}

