@Transactional
public RegistrationResponse cancel(long id, Instant now) {
    RegistrationRow row = find or 404;
    if (row.status() == CANCELLED) {
        return toResponse(row, List.of(), "备案已注销（幂等成功）");
    }
    if (row.status() != EFFECTIVE) throw conflict("仅生效备案可注销，当前状态: " + status);
    int updated = repo.markCancelled(id, now);
    if (updated != 1) throw conflict("注销失败，状态已变更");
    productRepository.updateStatus(row.productId(), "CANCELLED");
    return toResponse(reloaded, List.of(), "备案已注销");
}
